#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.

# Provisions v2's cloud (#109): a Hetzner VPS, dandori.simopzz.com on Porkbun,
# a Supabase project in Frankfurt with magic links sent through Resend, and a
# Grafana Cloud stack. See docs/adr/0017-hosted-on-hetzner-with-docker-compose.md.
# What it captures goes to .env.provision (gitignored) and to the GitHub
# secrets and variables CI deploys with.

DOMAIN=dandori.simopzz.com
ADMIN_KEY="$HOME/.ssh/dandori"
DEPLOY_KEY="$HOME/.ssh/dandori_deploy"

# copy TEXT puts it on the clipboard, when there is one.
copy() {
  if command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  else return 1; fi
  printf '  %s✓ copied to the clipboard%s\n' "$GREEN" "$RESET"
}

# resolves NAME TYPE WANT waits until public DNS answers NAME's TYPE record with WANT.
resolves() {
  local got
  for _ in $(seq 1 60); do
    got=$(dig +short @1.1.1.1 "$1" "$2" | tail -n1)
    if [[ "$got" == "$3" ]]; then
      printf '  %s✓%s %s %s → %s\n' "$GREEN" "$RESET" "$1" "$2" "$got"
      return 0
    fi
    note "$1 $2 answers '${got:-nothing}' yet, retrying in 10s…"
    sleep 10
  done
  return 1
}

run_wizard() {

cd "$(git rev-parse --show-toplevel)"
ENV_FILE=.env.provision
TOTAL_STAGES=8

for tool in gh ssh-keygen ssh-keyscan dig curl jq base64; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing: install it and run again"; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in: run 'gh auth login' and run again"; exit 1; }

banner "Provision Dandori v2's cloud"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "SSH keys and the server's cloud-init"
say "Two keys: one for you to administer the server as root, one for CI to deploy as 'deploy'."
for key in "$ADMIN_KEY" "$DEPLOY_KEY"; do
  if [[ -f "$key" ]]; then
    note "$key exists, kept"
  else
    ssh-keygen -q -t ed25519 -N "" -C "$(basename "$key")@$DOMAIN" -f "$key"
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$key"
  fi
done
set_secret DEPLOY_SSH_KEY "$(cat "$DEPLOY_KEY")"
CLOUD_INIT="#cloud-config
package_update: true
package_upgrade: true
packages: [docker.io, docker-compose-v2, ufw, unattended-upgrades]
users:
  - default
  - name: deploy
    shell: /bin/bash
    ssh_authorized_keys:
      - $(cat "$DEPLOY_KEY.pub")
ssh_pwauth: false
runcmd:
  - usermod -aG docker deploy
  - mkdir -p /srv/dandori && chown deploy:deploy /srv/dandori
  - sed -i 's/^#\\?PasswordAuthentication.*/PasswordAuthentication no/; s/^#\\?PermitRootLogin.*/PermitRootLogin prohibit-password/' /etc/ssh/sshd_config
  - systemctl reload ssh
  - ufw allow 22/tcp && ufw allow 80/tcp && ufw allow 443/tcp && ufw --force enable
  - systemctl enable --now docker unattended-upgrades"
copy "$CLOUD_INIT" || { say "Copy this cloud-init for the next stage:"; printf '%s\n' "$CLOUD_INIT"; }
note "The cloud-init is on your clipboard for the next stage. Your admin public key:"
note "$(cat "$ADMIN_KEY.pub")"
pause "Continue to Hetzner?"

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Hetzner: the server"
open_url "https://console.hetzner.com/projects"
step "Create a project named 'dandori' (or open it), then Servers → Add Server."
step "Location: Nuremberg (or Falkenstein). Image: the latest Ubuntu LTS."
step "Type: shared vCPU, x86, the cheapest with at least 2 GB RAM (the Cost-Optimized line may be sold out)."
step "Networking: keep Public IPv4 and Public IPv6 (GitHub's runners can't reach IPv6)."
step "SSH keys: Add SSH key, paste the admin public key shown in the last stage, keep the name it suggests."
step "Cloud config: paste the clipboard (it starts with #cloud-config)."
step "Name: dandori. Create & Buy now, then wait until it's running."
ask SERVER_IPV4 "Paste the server's IPv4:"
ask SERVER_IPV6 "Paste the server's IPv6 (the /64 network is fine):"
SERVER_IPV6="${SERVER_IPV6%/64}"
[[ "$SERVER_IPV6" == *:: ]] && SERVER_IPV6="${SERVER_IPV6}1"
write_env SERVER_IPV4 "$SERVER_IPV4"
write_env SERVER_IPV6 "$SERVER_IPV6"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Server check"
say "Waiting for cloud-init to finish installing Docker (a few minutes on a new server)…"
until ssh -i "$ADMIN_KEY" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=5 "root@$SERVER_IPV4" true 2>/dev/null; do
  note "SSH not up yet, retrying in 10s…"; sleep 10
done
ssh -i "$ADMIN_KEY" "root@$SERVER_IPV4" cloud-init status --wait
ssh -i "$DEPLOY_KEY" -o StrictHostKeyChecking=accept-new "deploy@$SERVER_IPV4" docker compose version
set_secret DEPLOY_HOST "$SERVER_IPV4"
set_secret DEPLOY_KNOWN_HOSTS "$(ssh-keyscan -t ed25519 "$SERVER_IPV4" 2>/dev/null)"
pause "Docker answered as 'deploy'. Continue to DNS?"

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Porkbun: $DOMAIN"
open_url "https://porkbun.com/account/domainsSpeedy"
step "On simopzz.com, open DNS (Details → DNS Records)."
step "Add: type A, host 'dandori', answer $SERVER_IPV4."
step "Add: type AAAA, host 'dandori', answer $SERVER_IPV6."
pause "Added both?"
resolves "$DOMAIN" A "$SERVER_IPV4" || warn "A record not visible yet: check it on Porkbun"
resolves "$DOMAIN" AAAA "$SERVER_IPV6" || warn "AAAA record not visible yet: check it on Porkbun"
set_var DANDORI_DOMAIN "$DOMAIN"
pause "Continue to Supabase?"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Supabase: the project"
DB_PASSWORD=$(_existing DB_PASSWORD || head -c 24 /dev/urandom | base64 | tr -d '/+=')
write_env DB_PASSWORD "$DB_PASSWORD"
copy "$DB_PASSWORD" || note "Database password: $DB_PASSWORD"
open_url "https://supabase.com/dashboard/new"
step "Name: dandori. Database password: paste the clipboard (also saved in $ENV_FILE)."
step "Region: Central EU (Frankfurt). Security: Data API off (Dandori talks to Postgres directly), automatic RLS on."
step "Create, and wait until it's ready. If you typed another password, put it in $ENV_FILE as DB_PASSWORD and re-run."
step "The project ref is in its URL: supabase.com/dashboard/project/<ref>."
ask SUPABASE_REF "Paste the project ref:"
write_env SUPABASE_URL "https://$SUPABASE_REF.supabase.co"
step "Project Settings → API Keys: copy the Publishable key (sb_publishable_…)."
ask SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
step "Connect (top bar) → Session pooler → copy the URI (it has [YOUR-PASSWORD] in it)."
note "Not the direct connection: it is IPv6 only, which Docker's default network and GitHub's runners can't reach."
ask DB_URI "Paste the URI:"
DANDORI_DATABASE_URL="${DB_URI/\[YOUR-PASSWORD\]/$DB_PASSWORD}"
write_env DANDORI_DATABASE_URL "$DANDORI_DATABASE_URL"
set_secret DANDORI_DATABASE_URL "$DANDORI_DATABASE_URL"
set_var SUPABASE_URL "$SUPABASE_URL"
set_var SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
pause "Continue to Resend?"

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Resend: send from simopzz.com"
say "Supabase only emails its own team unless it has its own SMTP: magic links go through Resend."
open_url "https://resend.com/domains"
step "Add Domain: simopzz.com, region EU (Ireland)."
step "Resend lists DNS records (MX and TXT on 'send', TXT on 'resend._domainkey')."
step "Add each on Porkbun (simopzz.com → DNS), the host without '.simopzz.com'."
step "Back on Resend, Verify DNS Records, and wait until the domain shows Verified."
pause "Verified?"
open_url "https://resend.com/api-keys"
step "Create API Key: name 'dandori-supabase', permission Sending access, domain simopzz.com."
step "Copy it, and keep it on the clipboard for the next stage: it isn't saved anywhere else."
pause "Copied?"

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Supabase: sign-in by invite and magic link"
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/smtp"
step "Authentication → Emails → SMTP Settings: enable custom SMTP."
step "Sender email dandori@simopzz.com, sender name Dandori."
step "Host smtp.resend.com, port 465, username resend, password: paste the Resend API key. Save."
pause "Saved?"
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/providers"
step "Authentication → Sign In / Providers: turn 'Allow new users to sign up' off; keep Email enabled. Save."
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/url-configuration"
step "Authentication → URL Configuration: Site URL https://$DOMAIN; add Redirect URL https://$DOMAIN/**. Save."
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/settings/jwt"
step "Project Settings → JWT Keys: the current key must be asymmetric (ECC or RSA)."
step "If the current one is the Legacy JWT secret: migrate it, then rotate to the new key."
pause "Done?"
until [[ "$(curl -fsS "$SUPABASE_URL/auth/v1/.well-known/jwks.json" | jq '.keys | length')" -gt 0 ]]; do
  warn "the JWKS endpoint returns no keys: the project still signs with the legacy secret"
  pause "Switch to asymmetric keys on JWT Keys, then press Enter to check again"
done
printf '  %s✓%s JWKS endpoint returns signing keys\n' "$GREEN" "$RESET"
pause "Continue to Grafana Cloud?"

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Grafana Cloud: where spans and logs go"
open_url "https://grafana.com/auth/sign-in"
step "My Account → Add Stack (or use yours): name dandori, region in the EU."
step "On the stack: OpenTelemetry → Configure → Generate now (an API token)."
step "The page shows the environment variables to copy."
ask OTEL_EXPORTER_OTLP_ENDPOINT "Paste OTEL_EXPORTER_OTLP_ENDPOINT (ends in /otlp):"
ask_secret OTEL_EXPORTER_OTLP_HEADERS "Paste OTEL_EXPORTER_OTLP_HEADERS (Authorization=Basic …):"
OTEL_EXPORTER_OTLP_HEADERS="${OTEL_EXPORTER_OTLP_HEADERS#\"}"; OTEL_EXPORTER_OTLP_HEADERS="${OTEL_EXPORTER_OTLP_HEADERS%\"}"
auth="${OTEL_EXPORTER_OTLP_HEADERS#Authorization=}"; auth="${auth//%20/ }"
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H "Authorization: $auth" \
  -H 'Content-Type: application/json' -d '{"resourceSpans":[]}' "$OTEL_EXPORTER_OTLP_ENDPOINT/v1/traces")
if [[ "$code" == 2* ]]; then
  printf '  %s✓%s Grafana Cloud accepted a test export (HTTP %s)\n' "$GREEN" "$RESET" "$code"
else
  warn "Grafana Cloud answered HTTP $code: check the endpoint and the header, then run again"
fi
write_env OTEL_EXPORTER_OTLP_ENDPOINT "$OTEL_EXPORTER_OTLP_ENDPOINT"
write_env OTEL_EXPORTER_OTLP_HEADERS "$OTEL_EXPORTER_OTLP_HEADERS"
set_secret OTEL_EXPORTER_OTLP_ENDPOINT "$OTEL_EXPORTER_OTLP_ENDPOINT"
set_secret OTEL_EXPORTER_OTLP_HEADERS "$OTEL_EXPORTER_OTLP_HEADERS"

finish
say "Next: invite yourself from Supabase (Authentication → Users → Invite user) once #112 lands."
}

run_wizard "$@"; exit
